examples.setup:
val today = 1_793_750_400_000L
var due by remember { mutableStateOf<Long?>(null) }
val state = rememberDatePickerState(initialSelectedDateMillis = today)
val presetList = listOf("Today" to 0L, "Tomorrow" to 1L, "In a week" to 7L, "In two weeks" to 14L)
val format = remember {
    DateFormat.getDateInstance(DateFormat.SHORT, Locale.forLanguageTag("en-GB")).apply { timeZone = TimeZone.getTimeZone("UTC") }
}
val dayFormat = remember {
    android.icu.text.SimpleDateFormat("EEE, d MMM", Locale.forLanguageTag("en-GB")).apply { timeZone = android.icu.util.TimeZone.getTimeZone("UTC") }
}

val today = remember { System.currentTimeMillis() / 86_400_000L * 86_400_000L }
val state = rememberDatePickerState(
    selectableDates = object : SelectableDates {
        override fun isSelectableDate(utcTimeMillis: Long): Boolean = utcTimeMillis >= today
    },
)
